{"kind":"stack","id":"s-sound","title":"How sounds are made","theme":{"background":"#1e3a5f","foreground":"#ffffff","font":"Georgia, serif"}}
{"kind":"card","card":{"id":"c1","kind":"flash","elements":[{"type":"text","id":"c1-t","content":"Vibration"},{"type":"text","id":"c1-e","content":"A quick shaking or trembling back and forth. Vibrations make sound."},{"type":"button","id":"c1-b","label":"Next Card","actions":[{"type":"goto","cardId":"c2"}]}],"actions":[]}}
